type TCompileOptions = {
	configFileName: (string | undefined)
	hCompilerInfo: (TCompilerInfo | undefined)
	}

class CFileCompiler extends CFileHandler {

	hCompilerInfo: (TCompilerInfo | undefined) = undef

	get op() {
		return 'doCompileFile'
	}

	// ..........................................................

	async canHandle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<boolean> {

		const {configFileName, hCompilerInfo} = getOptions<TCompileOptions>(hOptions, {
			configFileName: undef,
			hCompilerInfo: undef
			})

		const ext = fileExt(path)
		if (notdefined(ext)) {
			return false
		}

		assert(!allDefined(configFileName, hCompilerInfo),
			"Options configFileName and hCompilerInfo both set")
		const hCompilerInfo1 = (
			(defined(hCompilerInfo)?
				hCompilerInfo
			:
				(await getCompilerInfo(ext, configFileName)))
			);this.hCompilerInfo = hCompilerInfo1;
		if (notdefined(this.hCompilerInfo)) {
			DBG(`no compiler info for ext ${OL(ext)}`, UNDENT)
			return false
		}
		return true
	}

	// ..........................................................
	// ASYNC

	override allOutPaths(
			path: string,
			hOptions: hash = {}
			): string[] {

		obviously(defined(this.hCompilerInfo))
		const {getOutPaths} = this.hCompilerInfo
		return getOutPaths(path)
	}

	// ..........................................................

	override async postProcess(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		const {purpose} = parsePath(path)
		if (isEmpty(purpose)) {
			return {
				success: true,
				notNeeded: true
				}
		}
		obviously(defined(purpose))
		const postProc = await getPostProcessor(purpose)
		if (notdefined(postProc)) {
			return {
				success: true,
				notNeeded: true
				}
		}
		DBG("post-processing file")
		try {
			return await postProc(path, hOptions)
		}
		catch (err) {
			return {
				success: false,
				stderr: getErrStr(err)
				}
		}
	}

	// ..........................................................
	// --- file existence has already been checked.

	override async handle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		DBG(`COMPILE: ${OL(path)}`, INDENT)
		const {stub, purpose, ext} = parsePath(path)
		obviously(defined(this.hCompilerInfo))
		const {compiler} = this.hCompilerInfo

		DBG(`compiling ${OL(path)}`)
		const hResult = await compiler(path, hOptions)
		const {success} = hResult

		DBG(UNDENT)
		return hResult
	}
}

export const doCompileFile = new CFileCompiler()

// ---------------------------------------------------------------------------
// --- path will be the file being tested, e.g.
//        path = src/lib/datatypes.lib.civet
//        the file to execute is named datatypes.lib.test.civet
// --- If the test file doesn't exist, we want to report 0 passed and 0 failed

class CUnitTester extends CFileHandler {

	hPathInfo: (TPathInfo | undefined)

	get op() {
		return 'doUnitTest'
	}

	// ..........................................................

	async canHandle(
			path: string,
			hOptions: hash = {}
			) {

		this.hPathInfo = parsePath(path)
		const {stub, purpose, ext} = this.hPathInfo
		return (ext === '.ts') || (purpose !== 'test')
	}

	// ..........................................................

	async handle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		type opt = {
			capture: boolean
			inspect: boolean
			lineNum: (string | undefined)
			}
		const {capture, inspect, lineNum} = getOptions<opt>(hOptions, {
			capture: true,
			inspect: false,
			lineNum: undef
			})

		obviously(defined(this.hPathInfo))
		const {stub, purpose} = this.hPathInfo
		const testPath = findFile(`${stub}.${purpose}.test.civet`)
		if (notdefined(testPath)) {
			return {
				success: true,
				stdout: ' 0 passed | 0 failed',
				stderr: ''
				}
		}
		const tsPath = withExt(testPath, '.ts')
		const hResult = await procOneFile(testPath, doCompileCivet)
		assert(hResult.success && isFile(tsPath),
			`Compile of ${testPath} failed`)
		return this.runTest(tsPath, hOptions)
	}

	// ..........................................................

	async runTest(
			tsPath: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		type opt = {
			capture: boolean
			inspect: boolean
			lineNum: (string | undefined)
			}
		const {capture, inspect, lineNum} = getOptions<opt>(hOptions, {
			capture: true,
			inspect: false,
			lineNum: undef
			})

		return await execCmd('deno', [
				'test',
				'-A',
				'--trace-leaks',
				...(inspect
					? ['--inspect-brk']
					: ['--coverage=./coverage', '--coverage-raw-data-only']
					),
				...(defined(lineNum)
					? ['--filter', `/^line ${lineNum}$/`]
					: []
					),
				tsPath
				], {capture})
	}

	// ..........................................................

	override getOutput(
			hResult: TExecResult
			): string {

		const {stdout, stderr} = hResult
		const output = [stdout, stderr].join()
		if (!hResult.success || matches(output, /\b(croak|error)\b/i)) {
			return output
		}

		const lLines = Array.from(MAP(allLinesIn(decolorize(output)), function*(line) {
			if (line.startsWith('line') || line.startsWith('--->')) {
				if (!line.includes(' ok ')) {
					yield withColors(line, {
						failed: 'red',
						FAILED: 'red',
						ok: 'green',
						OK: 'green'
						})
				}
			}
			else if (line.includes('Lcov coverage')) {
				yield 'coverage report generated'
			}
			else {
				const lMatches = line.match(/\s+(\d+)\s+passed\s+\|\s+(\d+)\s+failed\b/)
				if (defined(lMatches)) {
					const [_, numPassed, numFailed] = lMatches
					const lParts = [
						(numPassed === '0') ? red("0 passed")   : green(`${numPassed} passed`),
						(numFailed === '0') ? green("0 failed") : red(`${numFailed} failed`)
						]
					yield lParts.join(' | ')
				}
			}
		}))
		return lLines.join('\n')
	}
}

export const doUnitTest = new CUnitTester()

